CREATE TRIGGER tax_notice_appeal_deadline_trigger BEFORE INSERT OR UPDATE OF notice_date, received_at, delivery_method, recipient_name, recipient_country_code, recipient_locality, recipient_local_holiday_dates, recipient_bavaria_assumption_applies, authority_name, authority_country_code, authority_locality, authority_local_holiday_dates, authority_bavaria_assumption_applies, date_basis, delivery_evidence_status, legal_remedy_instruction_status, access_status, access_evidence_status, recipient_region, authority_region, recipient_holiday_context_status, authority_holiday_context_status, retrieval_issued_at, retrieval_notification_date, retrieval_notification_status, retrieval_notification_disputed_or_late, retrieval_notification_legacy_fallback, retrieval_consent_status, retrieval_postal_request_status, retrieval_postal_request_received_at, retrieval_eligibility_2027_status, retrieved_at, appeal_deadline, calculated_notification_date, internal_risk_deadline, alternative_claimed_access_deadline, deadline_calculation_status, deadline_calculation_version, manual_review_required, retrieval_reinstatement_review_required ON public.tax_notice FOR EACH ROW EXECUTE FUNCTION app.tax_notice_set_appeal_deadline();
